<?php
declare(strict_types=1);namespace Vendi\Http;use PDO;use RuntimeException;use Vendi\Auth\PermissionService;
final class ApiGuard{public static function session():array{if(session_status()!==PHP_SESSION_ACTIVE)session_start();$u=$_SESSION['user']??null;if(!$u)throw new RuntimeException('Sesión requerida.',401);return$u;}public static function csrf():void{if(($_SERVER['REQUEST_METHOD']??'GET')==='GET')return;$sent=$_SERVER['HTTP_X_CSRF_TOKEN']??'';$expected=$_SESSION['csrf_token']??'';if(!$expected||!$sent||!hash_equals($expected,$sent))throw new RuntimeException('Solicitud inválida. Actualiza la página e intenta de nuevo.',403);}public static function permission(PDO$db,array$u,string$code):void{if(in_array($u['role']??'',['owner','admin'],true))return;if(!(new PermissionService($db))->can((int)$u['id'],$code))throw new RuntimeException('No tienes permiso para realizar esta operación.',403);}public static function branch(PDO$db,array$u,int$branch):void{if(in_array($u['role']??'',['owner','admin'],true))return;$q=$db->prepare("SELECT 1 FROM user_branches ub JOIN branches b ON b.id=ub.branch_id WHERE ub.user_id=? AND ub.branch_id=? AND b.business_id=? AND b.status='active' LIMIT 1");$q->execute([(int)$u['id'],$branch,(int)$u['business_id']]);if(!$q->fetchColumn())throw new RuntimeException('Sucursal no autorizada.',403);}}
